// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.deal(address(this), amount);
        uint256 beforeCount = c.depositsCount();
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "deposit failed");
        uint256 afterCount = c.depositsCount();
        assertTrue(afterCount == beforeCount + 1);
    }
}
